# Zugangsvoraussetzungen, Beantragung und allgemeine Teilnahmebedingungen.
package o6_3

# O6_3-COMB-01: zeitgleiche Teilnahme an UBB, BIO oder BIO-Teilbetrieb.
companion_measures := {m | some m in data.o6_3.combination_table.required_companion_measures_o6_3}

combination_obligation_met if {
	some m in participating_measures
	m in companion_measures
}

# SRL-COMB-02: UBB und BIO schließen einander betrieblich aus (ausgenommen Bio-Teilbetrieb).
farm_level_exclusion_violations contains ex if {
	some ex in data.o6_3.combination_table.farm_level_exclusions
	ex.measure_a in participating_measures
	ex.measure_b in participating_measures
	not bio_teilbetrieb_exception(ex)
}

bio_teilbetrieb_exception(ex) if {
	ex.exception == "Bio-Teilbetrieb"
	"o6_1b_teilbetrieb" in participating_measures
}

# O6_3-MIN-01: Mähwiesen und Mähweiden (ohne Streuwiesen/Bergmähder), inkl. Naturschutz-Flächen.
min_participation_area_ha := sum([p.area_ha |
	some p in parcels
	p.land_use == "grassland"
	grassland_type(p) in min_area_grassland_types
])

min_participation_area_met if min_participation_area_ha >= params.min_mown_grassland_first_year_ha

# O6_3-MIN-01 / O6_3-LH-01 / SRL-ACC-01: im ersten Verpflichtungsjahr zu erfüllende Zugangsvoraussetzungen.
access_requirement_failures contains "O6_3-COMB-01" if not combination_obligation_met

access_requirement_failures contains "SRL-COMB-02" if count(farm_level_exclusion_violations) > 0

access_requirement_failures contains "O6_3-MIN-01" if {
	is_first_contract_year
	not min_participation_area_met
}

access_requirement_failures contains "O6_3-LH-01" if {
	is_first_contract_year
	not is_livestock_farm
}

access_requirement_failures contains "GEN-MIN-01" if {
	is_first_oepul_year
	not farm_min_size_met
}

access_requirement_failures contains "GEN-ELIG-01" if not applicant_eligible

access_requirement_failures contains "O6_3-APP-01" if {
	is_first_contract_year
	not application_timely
}

access_requirement_failures contains "O6_3-APP-02" if {
	is_number(contract_start_year)
	contract_start_year > data.o6_3.contract_periods.measure_last_entry_year
}

access_requirements_met if count(access_requirement_failures) == 0

# SRL-ACC-01: Folgen fehlender Zugangsvoraussetzungen.
contract_established if {
	is_first_contract_year
	access_requirements_met
}

no_contract_first_year if {
	is_first_contract_year
	not access_requirements_met
}

no_premium_access_failure_later_year if {
	not is_first_contract_year
	not access_requirements_met
}

# GEN-MIN-01: Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr.
is_first_oepul_year if year == object.get(input, ["farm", "oepul", "first_participation_year"], null)

protected_cultivation_ha := object.get(input, ["land", "protected_cultivation_area_ha"], 0)

farm_min_size_met if protected_cultivation_ha >= params.farm_min_size_first_oepul_year.protected_cultivation_ha

farm_min_size_met if {
	sum([p.area_ha | some p in parcels]) + protected_cultivation_ha >= params.farm_min_size_first_oepul_year.agricultural_area_ha
}

# GEN-ELIG-01: förderwerbende Personen; Gebietskörperschaften sind bei Heuwirtschaft nicht zulässig.
applicant := object.get(input, ["farm", "applicant"], {})

applicant_eligible if {
	object.get(applicant, "legal_form", "natural_person") in {"natural_person", "registered_partnership"}
	not public_body_dominated
	object.get(applicant, "is_active_farmer", true) == true
}

applicant_eligible if {
	object.get(applicant, "legal_form", "") in {"legal_entity", "association"}
	not public_body_dominated
	object.get(applicant, "is_active_farmer", true) == true
}

public_body_dominated if object.get(applicant, "is_public_body", false) == true

public_body_dominated if object.get(applicant, "public_body_share_percent", 0) > params.public_body_max_share_percent

# O6_3-APP-01: Maßnahmenantrag bis 31.12. vor Vertragsbeginn.
application_date := object.get(o6_3_input, "measure_application_date", null)

application_timely if {
	is_string(application_date)
	is_number(contract_start_year)
	application_date <= sprintf("%d-12-31", [contract_start_year - 1])
}

# O6_3-APP-03 / O6_3-APP-04 / O6_3-CP-02: einjährige Option „Verzicht auf Mähaufbereiter“.
option_input := object.get(o6_3_input, "option_no_mower_conditioner", {})

option_requested if object.get(option_input, "applied", false) == true

option_active if {
	option_requested
	object.get(option_input, "marked_in_mfa_details", false) == true
	year <= data.o6_3.contract_periods.option_no_mower_conditioner.last_entry_year
}

option_application_issues contains "O6_3-APP-03" if {
	option_requested
	not object.get(option_input, "marked_in_mfa_details", false) == true
}

option_application_issues contains "O6_3-APP-04" if {
	option_requested
	year > data.o6_3.contract_periods.option_no_mower_conditioner.last_entry_year
}

# Allgemeine Teilnahmebedingungen und Sonderrichtlinie – für die Heuwirtschaft maßgebliche Abwicklungsregeln.
package o6_3

# O6_3-CP-01: Vertragszeitraum abhängig vom Vertragsbeginn, jedenfalls bis 31.12.2028.
contract_period := row if {
	some row in data.o6_3.contract_periods.rows
	row.start_year == contract_start_year
}

contract_end_year := 2028

within_contract_period if {
	is_number(contract_start_year)
	contract_start_year <= year
	year <= contract_end_year
}

# GEN-AREA-DEC-01: Toleranz für Flächenabgänge (5 %, max. 5 ha, jedenfalls 0,5 ha pro Jahr).
previous_year_grassland_ha := object.get(area_change, "previous_year_grassland_measure_area_ha", null)

tolerated_exempt_decrease_ha := object.get(area_change, "decrease_loss_of_disposal_ha", 0) + object.get(area_change, "decrease_permitted_conversion_ha", 0)

allowed_decrease_ha(prev) := max([
	min([prev * params.area_decrease_tolerance.max_share, params.area_decrease_tolerance.max_ha]),
	params.area_decrease_tolerance.always_allowed_ha,
])

current_grassland_measure_ha := object.get(area_change, "current_grassland_measure_area_ha", premium_grassland_area_ha)

relevant_decrease_ha := (previous_year_grassland_ha - current_grassland_measure_ha) - tolerated_exempt_decrease_ha if {
	is_number(previous_year_grassland_ha)
}

# Überschreitung: Rückzahlung für die gesamten Differenzflächen.
area_decrease_repayment_ha := relevant_decrease_ha if {
	relevant_decrease_ha > allowed_decrease_ha(previous_year_grassland_ha)
}

area_decrease_repayment_required if area_decrease_repayment_ha > 0

# GEN-EXIT-02 / SRL-ZA-01: vorzeitiger Ausstieg aus der mehrjährigen Maßnahme.
is_multi_year_measure if "o6_3" in data.o6_3.measure_lists.multi_year_measures

exit_input := object.get(o6_3_input, "exit", {})

exited_without_recognition if {
	is_multi_year_measure
	object.get(exit_input, "exited", false) == true
	object.get(exit_input, "exit_year", 9999) <= contract_end_year
	not object.get(exit_input, "force_majeure_or_exceptional_circumstances_recognised", false) == true
}

full_recovery_required if exited_without_recognition

full_recovery_required if object.get(o6_3_input, "payment_application_missing_over_one_year", false) == true

# SRL-ZA-01: fehlender Zahlungsantrag in einem Folgejahr – Verpflichtung bleibt, keine Zahlung.
no_payment_missing_application if object.get(o6_3_input, "payment_application_submitted", true) == false

# GEN-TAKEOVER-01: Maßnahmenübernahme bis 15.04. (2023 und 2028: 17.04.), Ausweitung max. 50 %.
takeover := object.get(o6_3_input, "takeover", {})

takeover_deadline(y) := sprintf("%d-%s", [y, params.takeover.deadline_month_day_2023_2028]) if {
	y in {2023, 2028}
} else := sprintf("%d-%s", [y, params.takeover.deadline_month_day])

takeover_issues contains "GEN-TAKEOVER-01" if {
	object.get(takeover, "is_takeover", false) == true
	object.get(takeover, "takeover_date", "9999-12-31") > takeover_deadline(year)
}

takeover_issues contains "GEN-TAKEOVER-01" if {
	object.get(takeover, "is_takeover", false) == true
	object.get(takeover, "extension_share", 0) > params.takeover.max_extension_share
}

takeover_issues contains "GEN-TAKEOVER-01" if {
	object.get(takeover, "is_takeover", false) == true
	object.get(takeover, "taker_already_participating", false) == true
}

# GEN-SANC-01: Kürzungsstufen; ab 2027 statt Verwarnung 1 % Einbehalt.
sanction_share(level, y) := s if {
	level == "warning"
	y >= params.warning_replaced_by_retention_from_year
	s := params.warning_retention_share
} else := s if {
	some l in data.o6_3.sanctions.levels
	l.level == level
	s := l.reduction_share
}

hundred_percent_reductions := object.get(o6_3_input, "hundred_percent_reductions_in_contract_period", 0)

excluded_from_measure if hundred_percent_reductions >= 2

# SRL-VOK-01: Verweigerung der Kontrolle führt zur Ablehnung und Rückabwicklung.
control_refused if object.get(input, ["farm", "oepul", "control_refused"], false) == true

# GEN-PAY-01: Auszahlung bis 30.06. des Folgejahres, Vorschuss max. 75 %.
payment_deadline := sprintf("%d-06-30", [year + 1])

max_advance_payment_eur := round((premium_after_modulation_eur * params.payment.advance_max_share) * 100) / 100

# GEN-LH-01: jährlicher Wechsel der Tierhaltereigenschaft; O6_3-PREM-03: keine Rückforderung für Vorjahre.
recovery_for_prior_years_due_to_livestock_change := false

# Eigenschaft als tierhaltender Betrieb (Merkblatt Kap. 4 und 8, SRL 1.5.4/1.5.5, Anhang A).
package o6_3

# O6_3-LH-03: RGVE-Umrechnungsfaktor je Tierkategorie laut RGVE-Schlüssel.
rgve_factor(category) := row.rgve_per_head if {
	some row in data.o6_3.rgve_key.rows
	row.category_id == category
}

# GEN-LH-01: Durchschnittsbestand (Rinderdatenbank bzw. Durchschnittstierliste) vor Stichtagsbestand.
group_head_count(g) := g.average_count if {
	is_number(object.get(g, "average_count", null))
} else := object.get(g, "animal_count", 0)

# O6_3-LH-02 / GEN-LOC-01: nur raufutterverzehrende Tiere der zulässigen Arten, im Inland gehalten.
rgve_group(g) if {
	object.get(g, "kept_in_austria", true) == true
	rgve_factor(object.get(g, "rgve_category", ""))
}

group_rgve(g) := group_head_count(g) * rgve_factor(g.rgve_category)

total_rgve := sum([group_rgve(g) | some g in species_groups; rgve_group(g)])

# O6_3-LH-04 / O6_3-LH-05 / O6_3-LH-06: Futterfläche = Grünland + Ackerfutterflächen (ohne Zweitkultur).
counts_as_forage_area(p) if p.land_use == "grassland"

counts_as_forage_area(p) if {
	p.land_use == "arable"
	forage_crop_type(p) in density_forage_crop_ids
	not is_second_crop(p)
}

forage_area_ha := sum([p.area_ha | some p in parcels; counts_as_forage_area(p)])

livestock_density := total_rgve / forage_area_ha if forage_area_ha > 0

# O6_3-LH-02: tierhaltender Betrieb ab 0,30 RGVE/ha Futterfläche.
is_livestock_farm if livestock_density >= params.livestock_density_threshold_rgve_per_ha

livestock_status := "tierhaltend" if {
	is_livestock_farm
} else := "nicht_tierhaltend"

# Förderverpflichtungen der Heuwirtschaft (Merkblatt Kap. 5, SRL 2.3.4) und Mindestbewirtschaftung.
package o6_3

feeding := object.get(input, ["farm", "feeding"], {})

machinery := object.get(input, ["farm", "machinery"], {})

forage_transfers := object.get(input, ["farm", "forage_transfers"], [])

flag(obj, key) if object.get(obj, key, false) == true

not_permitted_feed_ids := {f.id | some f in data.o6_3.feed_rules.not_permitted_feed_examples}

# O6_3-OBL-01: Verzicht auf Silagebereitung und Silagefütterung am gesamten Betrieb.
violations contains {"rule_id": "O6_3-OBL-01", "detail": "Silagebereitung am Betrieb"} if flag(feeding, "silage_produced")

violations contains {"rule_id": "O6_3-OBL-01", "detail": "Silagefütterung am Betrieb"} if flag(feeding, "silage_fed")

# O6_3-OBL-02: Pressen von nicht ohne Folie lagerfähigem Mähgut ist unzulässig.
violations contains {"rule_id": "O6_3-OBL-02", "detail": "Pressen von nicht ohne Folie lagerfähigem Mähgut"} if {
	flag(feeding, "non_storable_without_foil_pressed")
}

# O6_3-OBL-03: Grünmais/Grünfutter-Trocknung erlaubt, Gärungsprozess muss ausgeschlossen sein.
violations contains {"rule_id": "O6_3-OBL-03", "detail": "Gärungsprozess bei Grünfutter nicht ausgeschlossen"} if {
	flag(feeding, "green_forage_fermentation_occurred")
}

# O6_3-OBL-04: Futtermittel, bei deren Produktion eine Gärung (Silierung) stattfindet, sind nicht zugelassen.
violations contains {"rule_id": "O6_3-OBL-04", "detail": sprintf("Futtermittel mit Gärung: %v", [f.name])} if {
	some f in object.get(feeding, "feedstuffs", [])
	fermented_feed(f)
}

fermented_feed(f) if object.get(f, "fermentation_in_production", false) == true

fermented_feed(f) if object.get(f, "feed_id", "") in not_permitted_feed_ids

# O6_3-OBL-05: Heugewinnung kombiniert mit Grünfütterung im überwiegenden Teil der Vegetationsperiode.
green_feeding := object.get(feeding, "green_feeding", {})

green_feeding_days := object.get(green_feeding, "eingrasen_or_pasture_days_apr_sep", 0) + object.get(green_feeding, "communal_pasture_or_alm_days_apr_sep", 0)

green_feeding_majority_met if {
	green_feeding_days > params.vegetation_period.days * params.green_feeding_majority_share
	object.get(green_feeding, "all_roughage_animals_included", false) == true
}

violations contains {"rule_id": "O6_3-OBL-05", "detail": "Grünfütterung nicht im überwiegenden Teil der Vegetationsperiode für alle Raufutterverzehrer"} if {
	total_rgve > 0
	not green_feeding_majority_met
}

# O6_3-OBL-06: generelles Lagerungsverbot, auch keine Aufbrauchfrist für Silagevorräte.
violations contains {"rule_id": "O6_3-OBL-06", "detail": "Lagerung von Silage am Betrieb"} if flag(feeding, "silage_stored")

violations contains {"rule_id": "O6_3-OBL-06", "detail": "Aufbrauchen betriebseigener Silagevorräte nach Vertragsbeginn"} if {
	flag(feeding, "own_silage_stock_used_after_contract_start")
}

# O6_3-OBL-07: Abgabe von Mähgut an Dritte nur als trockenes Heu.
violations contains {"rule_id": "O6_3-OBL-07", "detail": sprintf("Mähgutabgabe in Form %v", [t.form])} if {
	some t in forage_transfers
	t.form != "dry_hay"
}

# O6_3-OBL-08: einmaliges Kreiseln mit anschließendem Wegfahren unzulässig.
violations contains {"rule_id": "O6_3-OBL-08", "detail": "einmaliges Kreiseln mit anschließendem Wegfahren"} if {
	some t in forage_transfers
	flag(t, "one_time_tedding_then_removed")
}

# O6_3-OBL-09: keine Maßnahmen, die auf Silageverwendung schließen lassen (auch außerhalb des Betriebes).
violations contains {"rule_id": "O6_3-OBL-09", "detail": "Hinweis auf Silageverwendung des Mähguts"} if {
	some t in forage_transfers
	flag(t, "indicates_silage_use")
}

# O6_3-OBL-10: keine Abgabe von Grünfutter zwischen zwei Heuwirtschaftsbetrieben.
violations contains {"rule_id": "O6_3-OBL-10", "detail": "Grünfutterabgabe an einen Heuwirtschaftsbetrieb"} if {
	some t in forage_transfers
	t.form == "green_forage"
	flag(t, "recipient_is_hay_farm")
}

# O6_3-OBL-11: kein Gärheu bzw. keine Heulage aus dem Aufwuchs.
violations contains {"rule_id": "O6_3-OBL-11", "detail": "Gärheu/Heulage"} if flag(feeding, "haylage_or_fermented_hay_produced")

# O6_3-OPT-01: bei Option kein Mähaufbereiter-Einsatz und kein Gerät am Betrieb.
violations contains {"rule_id": "O6_3-OPT-01", "detail": "Mähaufbereiter eingesetzt"} if {
	option_requested
	flag(machinery, "mower_conditioner_used")
}

violations contains {"rule_id": "O6_3-OPT-01", "detail": "Mähaufbereiter am Betrieb vorhanden"} if {
	option_requested
	flag(machinery, "mower_conditioner_present")
}

# GEN-MBK-01: Mindestbewirtschaftung auf Grünland und Ackerfutterflächen.
violations contains {"rule_id": "GEN-MBK-01", "detail": sprintf("Parzelle %v ohne Mahd/Beweidung", [p.parcel_id])} if {
	some p in parcels
	counts_as_forage_area(p)
	grassland_type(p) != "bergmaehder"
	not is_mown(p)
	not is_grazed(p)
}

violations contains {"rule_id": "GEN-MBK-01", "detail": sprintf("Bergmähder %v nicht innerhalb von 2 Jahren gemäht", [p.parcel_id])} if {
	some p in parcels
	grassland_type(p) == "bergmaehder"
	not is_mown(p)
	not object.get(p, ["operations", "mown_previous_year"], false) == true
}

violation_rule_ids := {v.rule_id | some v in violations}

# PREM-03: Förderbedingungen sind auch bei Nicht-Gewährung der Prämie einzuhalten.
obligations_apply if is_number(contract_start_year)

# Prämienberechnung Heuwirtschaft (Merkblatt Kap. 7, SRL 2.3.5, SRL 1.9, Anhang L).
package o6_3

# O6_3-PREM-01: Prämiensatz je Jahr, Tierhaltereigenschaft und Option.
rate_for(y, livestock, option) := row.eur_per_ha if {
	some row in data.o6_3.premium_rates.rows
	row.year_from <= y
	y <= row.year_to
	row.livestock_farm == livestock
	row.option_no_mower_conditioner == option
}

current_rate := rate_for(year, is_livestock_farm_bool, option_active_bool)

is_livestock_farm_bool if {
	is_livestock_farm
} else := false

option_active_bool if {
	option_active
} else := false

# O6_3-PREM-02: prämienfähige Flächen.
premium_area_class(p) := "grassland" if {
	p.land_use == "grassland"
	grassland_type(p) in premium_grassland_types
	is_mown(p)
}

premium_area_class(p) := "arable" if {
	p.land_use == "arable"
	forage_crop_type(p) in premium_forage_crop_ids
	not is_second_crop(p)
	is_mown(p)
}

# Ausschlüsse auf Einzelflächen (GEN-OP-01, GEN-AREA-01, GEN-AREA-02, GEN-COMB-02).
exclusion_rule_ids := {"GEN-OP-01", "GEN-AREA-01", "GEN-AREA-02", "GEN-COMB-02"}

parcel_exclusions(p) := {r | some r in exclusion_rule_ids; parcel_excluded_by(p, r)}

parcel_excluded_by(p, "GEN-OP-01") if "OP" in object.get(p, "oepul_codes", [])

parcel_excluded_by(p, "GEN-OP-01") if "o6_3" in object.get(p, "op_measures", [])

parcel_excluded_by(p, "GEN-AREA-01") if object.get(p, "non_eligible_area_type", null) in non_eligible_area_type_ids

non_eligible_area_type_ids := {t.id | some t in data.o6_3.area_eligibility.non_eligible_area_types}

parcel_excluded_by(p, "GEN-AREA-02") if {
	np := object.get(p, ["national_park", "name"], null)
	np in {n | some n in params.national_parks_without_area_premiums}
}

parcel_excluded_by(p, "GEN-AREA-02") if {
	object.get(p, ["national_park", "name"], null) != null
	object.get(p, ["national_park", "has_relevant_management_restrictions"], false) == true
}

parcel_excluded_by(p, "GEN-COMB-02") if {
	some m in parcel_measures(p)
	m != "o6_3"
	not single_parcel_combinable("o6_3", m)
}

# GEN-COMB-02: Anhang L – Kombinierbarkeit auf der Einzelfläche.
single_parcel_combinable(a, b) if {
	some cell in data.o6_3.combination_table.cells
	cell.row_measure == a
	cell.col_measure == b
}

single_parcel_combinable(a, b) if {
	a == "o6_3"
	b in {"o6_1a", "o6_1b", "o6_1b_teilbetrieb"}
}

premium_parcels := [{"parcel_id": p.parcel_id, "class": premium_area_class(p), "area_ha": p.area_ha} |
	some p in parcels
	premium_area_class(p)
	count(parcel_exclusions(p)) == 0
]

premium_grassland_area_ha := sum([pp.area_ha | some pp in premium_parcels; pp.class == "grassland"])

premium_arable_area_ha := sum([pp.area_ha | some pp in premium_parcels; pp.class == "arable"])

# GEN-AREA-INC-01: Flächenzugang auf Grünland ab 2026 max. +50 % bzw. +5 ha gegenüber 2025.
area_change := object.get(o6_3_input, "area_change", {})

base_2025_grassland_ha := object.get(area_change, "base_2025_grassland_measure_area_ha", null)

allowed_grassland_increase_ha := max([
	base_2025_grassland_ha * params.area_increase_restriction.max_increase_share,
	params.area_increase_restriction.always_allowed_increase_ha,
]) if {
	is_number(base_2025_grassland_ha)
}

eligible_grassland_area_ha := min([premium_grassland_area_ha, base_2025_grassland_ha + allowed_grassland_increase_ha]) if {
	"o6_3_grassland" in data.o6_3.measure_lists.area_increase_restricted_measures
	year > params.area_increase_restriction.base_year
	is_number(base_2025_grassland_ha)
} else := premium_grassland_area_ha

eligible_area_ha := eligible_grassland_area_ha + premium_arable_area_ha

# O6_3-PREM-01 / O6_3-PREM-03: Bruttoprämie (vor Kürzungen und Modulation).
premium_gross_eur := round((eligible_area_ha * current_rate) * 100) / 100 if {
	premium_payable_year
} else := 0

premium_payable_year if {
	contract_established
	not premium_blocked
}

premium_payable_year if {
	not is_first_contract_year
	within_contract_period
	access_requirements_met
	not premium_blocked
}

# GEN-EXIT-02, SRL-ZA-01, SRL-VOK-01: Gründe, aus denen im Antragsjahr keine Prämie gewährt wird.
premium_blocked if exited_without_recognition

premium_blocked if no_payment_missing_application

premium_blocked if control_refused

premium_blocked if excluded_from_measure

# GEN-MOD-01: Betriebsgrößenmodulation.
modulation_factor(total_ha) := 1 if total_ha <= 0

modulation_factor(total_ha) := f if {
	total_ha > 0
	parts := [part |
		some b in data.o6_3.modulation.brackets
		upper := bracket_upper(b, total_ha)
		upper > b.from_ha
		part := (upper - b.from_ha) * b.payout_share
	]
	f := sum(parts) / total_ha
}

bracket_upper(b, total_ha) := min([b.to_ha, total_ha]) if b.to_ha != null

bracket_upper(b, total_ha) := total_ha if b.to_ha == null

farm_total_area_ha := object.get(input, ["land", "total_area_ha"], 0)

premium_after_modulation_eur := round((premium_gross_eur * modulation_factor(farm_total_area_ha)) * 100) / 100

# SRL-PAY-02: Auszahlungsbetrag bis 50 Euro kann entfallen.
payout_may_be_waived if premium_after_modulation_eur <= params.payment.minimum_payout_eur

# GEN-CAP-01: Obergrenze der flächenbezogenen Zahlungen je ha.
cap_type(p) := "o6_18_o6_19" if {
	some m in parcel_measures(p)
	m in {"o6_18", "o6_19"}
} else := "general"

cap_for(y, t) := row.eur_per_ha if {
	some row in data.o6_3.premium_caps.rows
	row.cap_type == t
	row.year_from <= y
	y <= row.year_to
}

cap_exceeded_parcels contains p.parcel_id if {
	some pp in premium_parcels
	some p in parcels
	p.parcel_id == pp.parcel_id
	other := object.get(p, "other_capped_oepul_payments_eur_per_ha", 0)
	other + current_rate > cap_for(year, cap_type(p))
}

# NAT-GM01: Zuschlag im Naturschutz bei Teilnahme an der Heuwirtschaft (Anhang I).
naturschutz_gm01_surcharge_eur_per_ha := row.surcharge_if_o6_3_eur_per_ha if {
	"o6_3" in participating_measures
	some row in data.o6_3.naturschutz_interaction.rows
	row.code == "GM01"
}

